    private void syncAdapters(){if(updating)return;List<String> ids=new ArrayList<>();for(CaptureBackend.Adapter a:network.getSelectedValuesList())ids.add(a.id);adapterModel.clear();for(int i=0;i<adapters.getItemCount();i++)adapterModel.addElement(adapters.getItemAt(i));for(int i=0;i<adapterModel.size();i++)if(ids.contains(adapterModel.get(i).id))network.addSelectionInterval(i,i);if(network.isSelectionEmpty()&&adapterModel.size()>0)network.setSelectedIndex(0);controls();}
    void detect(){if(probing||running()||closed)return;probing=true;driver.setText("正在检测 Npcap…");controls();new SwingWorker<List<CaptureBackend.Adapter>,Void>(){protected List<CaptureBackend.Adapter> doInBackground()throws Exception{return CaptureBackend.probe();}protected void done(){probing=false;if(closed)return;try{List<CaptureBackend.Adapter> found=get();updating=true;adapters.removeAllItems();for(CaptureBackend.Adapter a:found)adapters.addItem(a);updating=false;syncAdapters();String saved=preferences.get("adapter","");for(int i=0;i<adapterModel.size();i++)if(adapterModel.get(i).id.equals(saved))network.setSelectedIndex(i);driver.setText(found.isEmpty()?"未发现网卡":"Npcap 已就绪 · "+found.size()+" 张网卡");driver.setForeground(Ui.POSITIVE);}catch(Exception e){updating=false;adapters.removeAllItems();driver.setText("Npcap 未就绪");message.setText(Ui.error(e));pages.setSelectedIndex(1);}controls();loadHistory();}}.execute();}
    private void preview(){try{String f=CaptureOptions.filter(address.getText(),protocol.getSelectedIndex(),ports.getText(),advanced.isSelected(),bpf.getText());effective.setText(f.isEmpty()?"当前保存全部流量。":"生效过滤："+f);}catch(IOException e){effective.setText(e.getMessage());}}
    private void chooseFolder(){JFileChooser c=new JFileChooser(folder);c.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(c.showOpenDialog(this)==JFileChooser.APPROVE_OPTION){folder=c.getSelectedFile();destination.setText(folder.getPath());preferences.put("folder",folder.getPath());}}
    void begin(boolean elevated){if(running()||closed||operation)return;try{
        if(!elevated){lastAdapters=network.getSelectedValuesList();if(lastAdapters.isEmpty()||lastAdapters.size()>8)throw new IOException("请选择 1～8 张网卡");lastFilter=CaptureOptions.filter(address.getText(),protocol.getSelectedIndex(),ports.getText(),advanced.isSelected(),bpf.getText());lastMode=new String[]{"single","rotate","ring"}[mode.getSelectedIndex()];lastChunk=(Integer)limit.getSelectedItem()*1048576L;lastBudget=lastMode.equals("single")?lastChunk+262200:(Integer)budget.getSelectedItem()*1024L*1048576;lastDuration=((Number)duration.getValue()).longValue()*60;output=CaptureTask.newDirectory(folder);preferences.put("adapter",lastAdapters.get(0).id);}
        historyIndexing=false;timer.stop();rateTime=-1;launching=true;latest=null;stopping=false;task=null;view=new LiveCaptureIndex.View();selectedCall="";synchronized(io){tailer.close();tailer=new CaptureTask.Tailer();appliedPins.clear();}refreshCalls();refreshFiles();phase.setText(elevated?"等待管理员授权":"正在打开网卡…");message.setText("正在校验所有网卡与过滤条件…");controls();
        new SwingWorker<CaptureBackend.Session,Void>(){protected CaptureBackend.Session doInBackground()throws Exception{return CaptureBackend.startTask(lastAdapters,lastFilter,output,lastMode,lastChunk,lastBudget,lastDuration,elevated);}protected void done(){launching=false;try{session=get();if(closed)session.stop();else {timer.start();pages.setSelectedIndex(0);}}catch(Exception e){phase.setText("未开始抓包");showError(e);}controls();}}.execute();
    }catch(Exception e){showError(e);}}
    boolean running(){return launching||session!=null;}
    void stop(){if(session==null||stopping)return;stopping=true;phase.setText("正在停止并保存…");controls();CaptureBackend.Session active=session;new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{active.stop();return null;}protected void done(){try{get();}catch(Exception e){stopping=false;showError(e);controls();}}}.execute();}
    private static final class Update {CaptureBackend.Snapshot snapshot;CaptureTask task;LiveCaptureIndex.View view;long pending;boolean caught;}
    private void poll(){if(session==null){pollHistory();return;}if(polling||operation||closed)return;polling=true;CaptureBackend.Session active=session;
        new SwingWorker<Update,Void>(){protected Update doInBackground()throws Exception{Update u=new Update();synchronized(io){u.snapshot=active.poll();if(u.snapshot!=null&&u.snapshot.values.containsKey("volumes")){u.task=new CaptureTask(active.output,u.snapshot.values);tailer.update(u.task,8L*1048576);u.view=tailer.index.view();u.pending=tailer.pending;u.caught=tailer.caughtUp();if(!active.ended())for(String id:u.task.pins){long end=tailer.index.pinEnd(id,u.caught);if(!Objects.equals(appliedPins.get(id),end)){Map<String,String> p=new HashMap<>();p.put("call",id);p.put("from",Long.toString(tailer.index.pinStart(id)));p.put("to",Long.toString(end));active.command("pin",p);appliedPins.put(id,end);}}}}return u;}
            protected void done(){polling=false;if(closed||session!=active)return;try{Update u=get();if(u.snapshot!=null){latest=u.snapshot;render(latest);}if(u.task!=null){task=u.task;view=u.view;refreshCalls();refreshFiles();liveStatus.setText(u.pending>0?String.format(Locale.ROOT,"速览落后 %.1f MiB；原始报文仍持续保存",u.pending/1048576.0):"速览已追上已提交报文 · 跨网卡重复合并 "+view.duplicateInterfaces+" 包（原始包保留）");}if(active.ended()){if(u.pending>0){stopping=true;phase.setText("已保存 · 正在补齐速览");controls();}else finish(active);}}catch(Exception e){message.setText("读取速览暂未完成："+Ui.error(e));if(!active.process.isAlive())finish(active);}}}.execute();
    }
    private void pollHistory(){if(!historyIndexing||task==null||polling||operation||closed)return;polling=true;CaptureTask current=task;
        new SwingWorker<Update,Void>(){protected Update doInBackground()throws Exception{synchronized(io){Update u=new Update();tailer.update(current,8L*1048576);u.view=tailer.index.view();u.pending=tailer.pending;return u;}}protected void done(){polling=false;if(closed||task!=current||running())return;try{Update u=get();view=u.view;refreshCalls();liveStatus.setText(u.pending>0?String.format(Locale.ROOT,"正在建立历史任务速览 · 剩余 %.1f MiB",u.pending/1048576.0):"历史任务速览已就绪");if(u.pending==0){historyIndexing=false;timer.stop();}}catch(Exception e){historyIndexing=false;timer.stop();showError(e);}}}.execute();}
    private void render(CaptureBackend.Snapshot s){if(rateTime>=0&&s.elapsed>rateTime)speed.setText(String.format(Locale.ROOT,"%.1f KiB/s · 磁盘 %.2f / %.2f GiB",Math.max(0,s.bytes-rateBytes)*1000.0/(s.elapsed-rateTime)/1024,Long.parseLong(s.values.getOrDefault("diskBytes","0"))/1073741824.0,Long.parseLong(s.values.getOrDefault("budget","0"))/1073741824.0));rateTime=s.elapsed;rateBytes=s.bytes;phase.setText(stopping&&!s.terminal()?"正在停止并保存…":s.phase.equals("running")?"● 正在抓包":s.phase.equals("done")?"抓包已保存":"抓包已中断");time.setText(String.format(Locale.ROOT,"%02d:%02d",s.elapsed/60000,s.elapsed/1000%60));packets.setText(String.format(Locale.ROOT,"%,d 包",s.packets));size.setText(String.format(Locale.ROOT,"%.1f MiB 已写入",s.bytes/1048576.0));drops.setText("驱动丢弃："+(s.drops==null?"不可用":s.drops));message.setText(s.message+(s.queueDrops>0?"\n写盘队列丢弃："+s.queueDrops+" 包":"")+(Long.parseLong(s.values.getOrDefault("policySkipped","0"))>0?"\n达到保存上限后未写入："+s.values.get("policySkipped")+" 包":""));}
    private void finish(CaptureBackend.Session active){session=null;timer.stop();stopping=false;active.cleanup();controls();if(closed)return;
        if(latest!=null&&latest.phase.equals("error")&&"open".equals(latest.values.get("kind"))&&!GraphicsEnvironment.isHeadless()){if(JOptionPane.showConfirmDialog(this,latest.message+"\n如 Npcap 限制管理员访问，可授权抓包组件重试。","网卡访问未完成",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){begin(true);return;}}
        if(task!=null){File directory=task.directory;new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{CaptureTask.remember(directory);return null;}protected void done(){loadHistory();}}.execute();if(automatic.isSelected()&&lastMode.equals("single")&&latest!=null&&latest.packets>0)snapshot(false,false);else if(!lastMode.equals("single")&&showFiles.isSelected())pages.setSelectedIndex(2);}else message.append("\n尚未创建可分析的任务文件。");
    }
    private void refreshCalls(){String keep=selectedCall;try{CallSearch.Filter f=new CallSearch.Filter();f.keyword=search.getText();f.caller=caller.getText();f.callee=callee.getText();f.ip=ip.getText();f.start=since.getText();f.end=until.getText();visibleCalls=CallSearch.find(view.calls,f);if(stateFilter.getSelectedIndex()>0){String q=(String)stateFilter.getSelectedItem();visibleCalls.removeIf(c->!c.status.contains(q));}
        Map<String,Set<String>> codecs=new HashMap<>();Map<String,Integer> count=new HashMap<>();Map<String,StringBuilder> digits=new HashMap<>();for(LiveCaptureIndex.Stream r:view.streams){codecs.computeIfAbsent(r.callId,k->new LinkedHashSet<>()).add(r.codec);count.put(r.callId,count.getOrDefault(r.callId,0)+1);}for(DtmfParser.Event e:view.events){StringBuilder d=digits.computeIfAbsent(e.callId,k->new StringBuilder());if(d.length()<80)d.append(e.key).append('[').append(e.typeCode()).append("] ");}Object[][] rows=new Object[visibleCalls.size()][7];int select=-1;for(int i=0;i<rows.length;i++){Call c=visibleCalls.get(i);rows[i]=new Object[]{Ui.stamp(c.startUs),CallSearch.number(c.from),CallSearch.number(c.to),c.status,count.containsKey(c.id)?count.get(c.id)+" 路 · "+String.join(" / ",codecs.get(c.id)):"未见媒体",digits.getOrDefault(c.id,new StringBuilder()).toString(),task!=null&&task.pins.contains(c.id)?"已保留":""};if(c.id.equals(keep))select=i;}updating=true;update(callTable,rows,"开始时间","主叫","被叫","状态","媒体","按键","保留");if(select>=0)callTable.setRowSelectionInterval(select,select);else if(!visibleCalls.isEmpty()){selectedCall=visibleCalls.get(0).id;callTable.setRowSelectionInterval(0,0);}else selectedCall="";updating=false;showCall();connections.setText(String.join("\n",view.connections)+(view.notice.isEmpty()?"":"\n"+view.notice));controls();
    }catch(IllegalArgumentException e){liveStatus.setText(e.getMessage());}}
    private void showCall(){Call c=view.call(selectedCall);if(c==null){StringBuilder clues=new StringBuilder("请选择通话。加密信令可打开任务快照并分别导入密钥。\n");int n=0;for(LiveCaptureIndex.Stream stream:view.streams)if(stream.callId.isEmpty()&&n++<20)clues.append("\n未关联 RTP：").append(stream.src).append(" → ").append(stream.dst).append(" · ").append(stream.codec).append(" · ").append(stream.packets).append(" 包");overview.setText(clues.toString());visibleSip=new ArrayList<>();update(sipTable,new Object[0][3],"时间","信令（最近 512 条中的本通话）","方向");return;}StringBuilder s=new StringBuilder(CallSearch.participants(c)).append("\n").append(CallSearch.times(c)).append(" · ").append(c.status).append("\nCall-ID：").append(c.id).append("\nIP：").append(String.join(" / ",c.signalingIps));List<String> names=new ArrayList<>();for(int n:view.sources.getOrDefault(c.id,Collections.emptySet()))names.add(task==null?Integer.toString(n):task.values.getOrDefault("label."+n,"接口 "+n));s.append("\n网卡：").append(String.join(" / ",names)).append(" · 关联分卷：").append(view.volumes.getOrDefault(c.id,Collections.emptySet()));for(LiveCaptureIndex.Stream stream:view.streams)if(stream.callId.equals(c.id))s.append("\n").append(stream.src).append(" → ").append(stream.dst).append(" · ").append(stream.codec).append(" · ").append(stream.packets).append(" 包 · 序号缺口 ").append(stream.gaps);s.append("\n按键：");boolean any=false;for(DtmfParser.Event e:view.events)if(c.id.equals(e.callId)){s.append(e.key).append(" [").append(e.typeCode()).append("] ");any=true;}if(!any)s.append("暂未识别到 2833 / INFO");s.append("\n缺口可能随后被乱序报文补齐；In-band、音频与体检请打开快照。");overview.setText(s.toString());overview.setCaretPosition(0);
        String previous=detail.original();visibleSip=new ArrayList<>();for(SipMessage m:view.messages)if(c.id.equals(m.callId))visibleSip.add(m);Object[][] rows=new Object[visibleSip.size()][3];for(int i=0;i<rows.length;i++){SipMessage m=visibleSip.get(i);rows[i]=new Object[]{Ui.stamp(m.timeUs),m.firstLine,m.src+" → "+m.dst};}update(sipTable,rows,"时间","信令（最近 512 条中的本通话）","方向");if(!visibleSip.isEmpty()&&(previous.isEmpty()||!previous.contains(c.id)))detail.showSip(visibleSip.get(visibleSip.size()-1));pin.setText(task!=null&&task.pins.contains(c.id)?"取消保留":"保留通话");}
    private void refreshFiles(){List<Integer> selected=new ArrayList<>();for(int i:fileTable.getSelectedRows())if(i<displayedVolumes.size())selected.add(displayedVolumes.get(i));Object[][] rows=new Object[task==null?0:task.volumes.size()][6];for(int i=0;i<rows.length;i++){CaptureTask.Volume v=task.volumes.get(i);rows[i]=new Object[]{v.file.getName(),String.format(Locale.ROOT,"%.1f MiB",v.bytes/1048576.0),v.packets,v.packets==0?"无报文":Ui.stamp(v.first)+" — "+Ui.stamp(v.last),v.closed?"已封存":"写入中",v.pinned?"已保留":"可轮转"};}update(fileTable,rows,"文件","大小","报文","时间范围","状态","保留");displayedVolumes.clear();if(task!=null)for(CaptureTask.Volume v:task.volumes)displayedVolumes.add(v.number);for(int i=0;i<rows.length;i++)if(selected.contains(task.volumes.get(i).number))fileTable.addRowSelectionInterval(i,i);if(task!=null)taskStatus.setText(task.directory.getPath()+"\n"+task.values.getOrDefault("message","")+"\n保留通话 "+task.pins.size()+" 个；快照超过 768 MiB 将自动分段，分段分别分析。");controls();}
    private void pin(){if(session==null||task==null||selectedCall.isEmpty()||operation)return;final CaptureBackend.Session active=session;final String id=selectedCall;final boolean remove=task.pins.contains(id);operation=true;controls();new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{synchronized(io){Map<String,String> p=new HashMap<>();p.put("call",id);p.put("from",Long.toString(tailer.index.pinStart(id)));p.put("to",Long.toString(tailer.index.pinEnd(id,tailer.caughtUp())));active.command(remove?"unpin":"pin",p);appliedPins.remove(id);}return null;}protected void done(){operation=false;if(closed)return;try{get();message.setText(remove?"已取消保留；循环模式可覆盖相关分卷。":"已保留关联分卷，持续保护至通话结束后 2 秒。TCP 通话同时保留此前连接上下文。已覆盖前段无法恢复。");}catch(Exception e){showError(e);}controls();poll();}}.execute();}
    private static long parseTime(String value,long fallback)throws IOException {if(value.trim().isEmpty())return fallback;String v=value.trim().replace('T',' ');for(String pattern:new String[]{"yyyy-MM-dd HH:mm:ss.SSS","yyyy-MM-dd HH:mm:ss","yyyy-MM-dd HH:mm"}){SimpleDateFormat parser=new SimpleDateFormat(pattern,Locale.ROOT);parser.setLenient(false);ParsePosition pos=new ParsePosition(0);Date d=parser.parse(v,pos);if(d!=null&&pos.getIndex()==v.length())return d.getTime()*1000;}throw new IOException("范围时间格式：yyyy-MM-dd HH:mm:ss");}
    private void snapshot(boolean byCall,boolean byRange){if(task==null||operation||closed)return;final CaptureBackend.Session active=session;final CaptureTask captured=task;final boolean callSelected=byCall||byRange&&rangeCall.getSelectedIndex()==1;final String id=callSelected?selectedCall:"";if(callSelected&&id.isEmpty()){message.setText("请先在实时通话中选择一通电话。");return;}
        final Set<Integer> selected=new HashSet<>();if(byRange)for(int i:fileTable.getSelectedRows())selected.add(captured.volumes.get(i).number);final long from,to;try{from=byRange?parseTime(rangeStart.getText(),0):0;to=byRange?parseTime(rangeEnd.getText(),Long.MAX_VALUE):Long.MAX_VALUE;if(from>to)throw new IOException("起始时间不能晚于结束时间");}catch(Exception e){showError(e);return;}operation=true;controls();message.setText("正在冻结完整报文边界并生成分析快照，抓包继续运行…");
        new SwingWorker<CaptureTask.SnapshotResult,Void>(){protected CaptureTask.SnapshotResult doInBackground()throws Exception{synchronized(io){File lease=active==null?null:new File(active.directory,"lease");try{CaptureTask frozen=captured;if(active!=null&&active.process.isAlive()){Files.write(lease.toPath(),new byte[0]);frozen=new CaptureTask(active.output,active.command("freeze",Collections.emptyMap()));}if(!id.isEmpty()){do{tailer.update(frozen,32L*1048576);}while(tailer.pending>0);}LiveCaptureIndex.Selection selection=id.isEmpty()?null:tailer.index.selection(id);if(!id.isEmpty()&&selection==null)throw new IOException("通话不在速览索引中，请选择任务分卷分析");return frozen.snapshot(new File(folder,"分析快照"),byRange&&!selected.isEmpty()?selected:null,from,to,selection);}finally{if(lease!=null)Files.deleteIfExists(lease.toPath());}}}
            protected void done(){operation=false;if(closed)return;try{CaptureTask.SnapshotResult r=get();String context="快照报文截至 "+new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS",Locale.ROOT).format(new Date(r.lastUs/1000))+"；后续报文不自动加入。"+(r.missing?"部分早期分卷已覆盖或数据不完整。":"")+(r.shared?"为保留 TCP / TLS 上下文，快照包含关联完整连接，可能含同连接其他通话。":"")+(r.files.size()>1?"快照已分为 "+r.files.size()+" 段，各段独立分析。":"");for(File file:r.files){queuedSnapshots.add(file);if(snapshotHandler!=null)snapshotHandler.accept(new SnapshotRequest(file,id,context));else completed.accept(file);}message.setText("快照已加入分析等待列表。"+context);}catch(Exception e){showError(e);}controls();}}.execute();
    }
    void analysisOpened(File file){if(!closed&&queuedSnapshots.remove(file))message.setText("文件已送入抓包分析，可查看信令、媒体和按键。"+(running()?"本机抓包仍在继续。":""));}
    private void loadHistory(){if(closed)return;new SwingWorker<List<CaptureTask>,Void>(){protected List<CaptureTask> doInBackground()throws Exception{return CaptureTask.history();}protected void done(){if(closed)return;try{loadingHistory=true;history.removeAllItems();for(CaptureTask t:get())history.addItem(t);loadingHistory=false;}catch(Exception e){loadingHistory=false;message.setText(Ui.error(e));}}}.execute();}
    private void chooseTask(){if(running()||operation)return;JFileChooser c=new JFileChooser(folder);c.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(c.showOpenDialog(this)==JFileChooser.APPROVE_OPTION){File directory=c.getSelectedFile();operation=true;controls();new SwingWorker<CaptureTask,Void>(){protected CaptureTask doInBackground()throws Exception{return CaptureTask.recover(directory);}protected void done(){operation=false;if(closed)return;try{openHistorical(get());}catch(Exception e){showError(e);}controls();}}.execute();}}
    private void openHistorical(CaptureTask value){if(running()||operation||closed)return;operation=true;controls();new SwingWorker<Update,Void>(){protected Update doInBackground()throws Exception{synchronized(io){tailer.close();tailer=new CaptureTask.Tailer();Update u=new Update();u.task=value.incomplete()&&!value.phase().equals("recovered")?CaptureTask.recover(value.directory):value;tailer.update(u.task,32L*1048576);u.view=tailer.index.view();u.pending=tailer.pending;CaptureTask.remember(value.directory);return u;}}protected void done(){operation=false;if(closed)return;try{Update u=get();task=u.task;output=task.directory;view=u.view;selectedCall="";historyIndexing=u.pending>0;if(historyIndexing)timer.start();refreshCalls();refreshFiles();phase.setText("已打开历史任务");message.setText("历史任务可生成快照，不会重新开始抓包。"+(u.pending>0?"速览正在后台补齐，可先选择分卷分析。":""));}catch(Exception e){showError(e);}controls();}}.execute();}
    private void controls(){boolean idle=!running()&&!closed&&!operation;start.setEnabled(idle&&!probing&&!network.isSelectionEmpty());stop.setVisible(running());stop.setEnabled(session!=null&&!stopping);refresh.setEnabled(idle&&!probing);network.setEnabled(idle&&!probing);for(JComponent c:new JComponent[]{advanced,bpf,folderButton,limit,automatic,showFiles,mode,duration,presets,applyPreset,savePreset})c.setEnabled(idle);budget.setEnabled(idle&&mode.getSelectedIndex()!=0);for(JComponent c:new JComponent[]{address,ports,protocol})c.setEnabled(idle&&!advanced.isSelected());boolean available=task!=null&&!task.volumes.isEmpty()&&!operation&&!closed;analyze.setVisible(available);analyze.setEnabled(available);snapshotRange.setEnabled(available);openCall.setEnabled(available&&view.call(selectedCall)!=null);pin.setEnabled(available&&session!=null&&view.call(selectedCall)!=null);history.setEnabled(idle);logs.setEnabled(task!=null&&!operation);}
    private void refreshPresets(){try{presets.removeAllItems();for(CapturePresets.Preset p:new CapturePresets(preferences).list())presets.addItem(p);}catch(IOException e){message.setText(e.getMessage());}}
    CapturePresets.Preset savePreset(String name)throws IOException {Map<String,String> p=new HashMap<>();List<String> ids=new ArrayList<>();for(CaptureBackend.Adapter a:network.getSelectedValuesList())ids.add(a.id);p.put("adapters",String.join("|",ids));p.put("address",address.getText());p.put("ports",ports.getText());p.put("protocol",Integer.toString(protocol.getSelectedIndex()));p.put("advanced",Boolean.toString(advanced.isSelected()));p.put("bpf",bpf.getText());p.put("mode",Integer.toString(mode.getSelectedIndex()));p.put("limit",limit.getSelectedItem().toString());p.put("budget",budget.getSelectedItem().toString());p.put("duration",duration.getValue().toString());p.put("folder",folder.getPath());p.put("automatic",Boolean.toString(automatic.isSelected()));p.put("showFiles",Boolean.toString(showFiles.isSelected()));CapturePresets.Preset result=new CapturePresets(preferences).save(name,p);refreshPresets();message.setText("抓包方案已保存在本机。只保存网卡、过滤与保存设置。");return result;}
    void applyPreset(CapturePresets.Preset preset)throws IOException {if(running()||operation)throw new IOException("抓包期间不能修改方案");Map<String,String> p=preset.settings;try{int protocolIndex=Integer.parseInt(p.get("protocol")),modeIndex=Integer.parseInt(p.get("mode")),chunk=Integer.parseInt(p.get("limit")),space=Integer.parseInt(p.get("budget")),minutes=Integer.parseInt(p.get("duration"));if(protocolIndex<0||protocolIndex>=protocol.getItemCount()||modeIndex<0||modeIndex>2||!Arrays.asList(128,256,512,768).contains(chunk)||!Arrays.asList(2,4,8,16).contains(space)||minutes<0||minutes>1440)throw new NumberFormatException();CaptureOptions.filter(p.get("address"),protocolIndex,p.get("ports"),Boolean.parseBoolean(p.get("advanced")),p.get("bpf"));protocol.setSelectedIndex(protocolIndex);mode.setSelectedIndex(modeIndex);limit.setSelectedItem(chunk);budget.setSelectedItem(space);duration.setValue(minutes);address.setText(p.get("address"));ports.setText(p.get("ports"));bpf.setText(p.get("bpf"));advanced.setSelected(Boolean.parseBoolean(p.get("advanced")));advancedBody.setVisible(advanced.isSelected());automatic.setSelected(Boolean.parseBoolean(p.get("automatic")));showFiles.setSelected(Boolean.parseBoolean(p.get("showFiles")));folder=new File(p.get("folder"));destination.setText(folder.getPath());Set<String> ids=new HashSet<>(Arrays.asList(p.get("adapters").split("\\|")));network.clearSelection();for(int i=0;i<adapterModel.size();i++)if(ids.contains(adapterModel.get(i).id))network.addSelectionInterval(i,i);message.setText("已应用本机方案："+preset.name+(network.getSelectedIndices().length<ids.size()?"；部分网卡不可用，请重新选择。":""));preview();controls();}catch(RuntimeException e){throw new IOException("抓包方案设置无效，请重新保存",e);}}
    private void showLog(){if(task==null)return;File file=new File(task.directory,"capture.log");logs.setEnabled(false);new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{if(!file.isFile())return "本任务暂无日志。";if(file.length()>300000)throw new IOException("任务日志超过读取上限");return new String(Files.readAllBytes(file.toPath()),java.nio.charset.StandardCharsets.UTF_8);}protected void done(){if(closed)return;try{JTextArea text=Ui.note(get());text.setFont(Ui.font(13));JDialog dialog=new JDialog((Frame)SwingUtilities.getWindowAncestor(CapturePanel.this),"本机抓包 · 任务日志",false);taskDialogs.add(dialog);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);dialog.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){taskDialogs.remove(dialog);}});dialog.setContentPane(Ui.scroll(text));Ui.fitWindow(dialog,800,520,500,320);dialog.setLocationRelativeTo(CapturePanel.this);dialog.setVisible(true);}catch(Exception e){showError(e);}controls();}}.execute();}
    private void showError(Throwable e){message.setText(Ui.error(e));if(!GraphicsEnvironment.isHeadless())JOptionPane.showMessageDialog(this,Ui.error(e),"本机抓包",JOptionPane.INFORMATION_MESSAGE);}
    boolean confirmExit(){if(!running())return true;if(JOptionPane.showConfirmDialog(this,"正在抓包。退出前需要停止并保存文件。是否停止后退出？","抓包尚未停止",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return false;final boolean[] saved={false};JDialog dialog=new JDialog((Frame)SwingUtilities.getWindowAncestor(this),"正在保存抓包",true);dialog.setContentPane(Ui.card(new BorderLayout()));dialog.add(Ui.label("正在停止并保存，请稍候…",14,Ui.INK));dialog.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);dialog.setSize(Ui.u(400),Ui.u(150));dialog.setLocationRelativeTo(this);new SwingWorker<Boolean,Void>(){protected Boolean doInBackground()throws Exception{long end=System.currentTimeMillis()+30000;while(launching&&System.currentTimeMillis()<end)Thread.sleep(50);CaptureBackend.Session s=session;if(s==null)return true;s.stop();return s.await(Math.max(1,end-System.currentTimeMillis()));}protected void done(){try{saved[0]=get();}catch(Exception e){showError(e);}dialog.dispose();}}.execute();dialog.setVisible(true);return saved[0];}
    public void close(){closed=true;timer.stop();searchTimer.stop();for(JDialog d:new ArrayList<>(taskDialogs))d.dispose();CaptureBackend.Session active=session;if(active!=null){try{active.stop();}catch(IOException ignored){}}new SwingWorker<Void,Void>(){protected Void doInBackground(){synchronized(io){tailer.close();}if(active!=null)try{active.await(15000);active.cleanup();}catch(InterruptedException e){Thread.currentThread().interrupt();}return null;}}.execute();}
